"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2945],{82142:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"HealthStaminaGuiController","desc":"Drives the authored `HealthStaminaGui` HUD\'s health and stamina bars from\\n`Signals.OnHealthValueChanged` / `Signals.OnStaminaValueChanged`.\\n\\nBoth bars are **horizontal** and are driven by the X scale of the bar Frame\\nitself \u2014 the parent of the three layered fill frames, not one of the layers\\nand not the enclosing `CanvasGroup`:\\n\\n```\\nMainContainer\\n\u251c\u2500\u2500 CanvasHealth   (CanvasGroup, ClipsDescendants) -- composites + clips\\n\u2502   \u2514\u2500\u2500 Health     (Frame)  <-- resize THIS\\n\u2502       \u251c\u2500\u2500 healthDarker / healthLighter / healthWhite  -- art layers\\n\u2514\u2500\u2500 CanvasStamina  (CanvasGroup, ClipsDescendants)\\n    \u2514\u2500\u2500 Stamina    (Frame)  <-- resize THIS\\n        \u2514\u2500\u2500 stamDarker / stamLighter / stamWhite\\n```\\n\\nResizing a layer distorts that layer only; resizing the `CanvasGroup` moves\\nthe whole widget including its backing art. Keep these names in sync with the\\nStudio asset \u2014 they are load-bearing.","realm":["Client"],"source":{"line":29,"path":"src/StarterPlayer/StarterPlayerScripts/HealthStaminaGuiController.client.luau"}}')}}]);